package com.example.editor.textual.interaction;

import java.util.List;
import org.springframework.stereotype.Component;
import com.example.editor.grammar.diagnostic.GrammarTextEdit;
import com.example.editor.textual.runtime.TextualModelSessionService;

/** Fachada de aplicación que fija cada consulta a una revisión last-known-good de la sesión. */
@Component
public class TextualInteractionFacade {
    private final TextualModelSessionService sessions;private final TextualLanguageFeatureService features;
    /** Descripción: Inicializa la fachada con servicios canónicos compartidos. Entradas: sessions y features. Salida: deja la instancia lista para resolver interacciones. */ public TextualInteractionFacade(TextualModelSessionService sessions,TextualLanguageFeatureService features){this.sessions=sessions;this.features=features;}
    /** Descripción: Publica capacidades neutrales disponibles para una sesión. Entradas: sessionId. Salida: devuelve la matriz común de capacidades. */ public List<TextualInteractionCapabilityState>capabilities(String sessionId){snapshot(sessionId);return features.capabilities();}
    /** Descripción: Ejecuta completion sobre un snapshot coherente. Entradas: sessionId y request. Salida: devuelve propuestas acotadas. */ public List<TextualCompletionItem>completion(String sessionId,TextualInteractionRequest request){return features.completion(snapshot(sessionId),request);}
    /** Descripción: Ejecuta hover sobre un snapshot coherente. Entradas: sessionId y request. Salida: devuelve información contextual. */ public TextualHoverInfo hover(String sessionId,TextualInteractionRequest request){return features.hover(snapshot(sessionId),request);}
    /** Descripción: Resuelve definición sobre un snapshot coherente. Entradas: sessionId y request. Salida: devuelve localización opcional o null para API. */ public TextualNavigationLocation definition(String sessionId,TextualInteractionRequest request){return features.definition(snapshot(sessionId),request).orElse(null);}
    /** Descripción: Resuelve referencias sobre un snapshot coherente. Entradas: sessionId y request. Salida: devuelve localizaciones acotadas. */ public List<TextualNavigationLocation>references(String sessionId,TextualInteractionRequest request){return features.references(snapshot(sessionId),request);}
    /** Descripción: Previsualiza rename sin mutar la sesión. Entradas: sessionId y request. Salida: devuelve un plan preview-first. */ public TextualRenamePlan rename(String sessionId,TextualRenameRequest request){return features.rename(snapshot(sessionId),request);}
    /** Descripción: Calcula formato determinista sin persistirlo. Entradas: sessionId y documentId. Salida: devuelve ediciones declarativas. */ public List<GrammarTextEdit>format(String sessionId,String documentId){return features.format(snapshot(sessionId),documentId);}
    /** Descripción: Obtiene símbolos de un documento fijados a la revisión válida. Entradas: sessionId y documentId. Salida: devuelve símbolos acotados. */ public List<TextualDocumentSymbol>symbols(String sessionId,String documentId){return features.documentSymbols(snapshot(sessionId),documentId);}
    /** Descripción: Obtiene rangos plegables de un documento fijados a la revisión válida. Entradas: sessionId y documentId. Salida: devuelve rangos acotados. */ public List<TextualFoldingRange>folding(String sessionId,String documentId){return features.folding(snapshot(sessionId),documentId);}
    /** Descripción: Obtiene tokens semánticos de un documento fijados a la revisión válida. Entradas: sessionId y documentId. Salida: devuelve tokens acotados. */ public List<TextualSemanticToken>tokens(String sessionId,String documentId){return features.semanticTokens(snapshot(sessionId),documentId);}
    /** Descripción: Calcula el cierre de invalidación incremental por documentos modificados. Entradas: sessionId y changedDocuments. Salida: devuelve el plan de reanálisis. */ public TextualDependencyInvalidationPlan invalidation(String sessionId,List<String>changedDocuments){return features.invalidation(snapshot(sessionId),changedDocuments);}
    /** Descripción: Evalúa compatibilidad de snapshots sin modificar la sesión. Entradas: request. Salida: devuelve política de reutilización/reparse/migración. */ public TextualSnapshotCompatibilityReport snapshotCompatibility(TextualSnapshotCompatibilityRequest request){return features.snapshotCompatibility(request);}
    /** Descripción: Construye una vista inmutable fijada a la revisión válida actual e impide mezclar documentos rotos con un source map anterior. Entradas: sessionId. Salida: devuelve un workspace coherente o falla de forma cerrada si el borrador actual no coincide con last-known-good. */ private TextualWorkspaceIndex snapshot(String sessionId){var stored=sessions.find(sessionId);var session=stored.document();if(session.lastValidSemanticModel()==null)throw new IllegalStateException("No last-known-good semantic model is available for textual interactions: "+sessionId);if(!session.draftValid()||session.lastParsedRevision()!=session.draftRevision())throw new IllegalStateException("Neutral textual interactions require the current draft to be the last-known-good revision; use the external native provider for broken drafts");return new TextualWorkspaceIndex(session.lastParsedRevision(),session.documents(),session.lastValidSemanticModel(),session.lastValidSourceMap());}
}
